/* Relik — телеметрия ошибок и событий.
   Пишет только то, что нужно для отладки: тип события, версия, короткий контекст.
   Тексты сообщений и ключи сюда не попадают никогда. */

import { sb, ensureClient } from './supabaseClient.js';
import { SUPABASE, APP } from '../config.js';
import { S } from '../ui/state.js';

const MAX_PER_SESSION = 60;
const BATCH_MS = 4000;

let queue = [];
let sent = 0;
let timer = null;
let ready = null;

/* Режим определяем по ключам: SDK загружается лениво, поэтому sb может быть
   ещё null — события просто копятся в очереди до его появления. */
const real = () => !!(SUPABASE.url && SUPABASE.anonKey);

function sanitize(data) {
  try {
    const s = JSON.stringify(data ?? {});
    return s.length > 1200 ? { truncated: s.slice(0, 1200) } : JSON.parse(s);
  } catch (e) {
    return { note: 'unserializable' };
  }
}

async function tableReady() {
  if (!real()) return false;
  if (ready !== null) return ready;
  try {
    const { error } = await sb.from('client_events').select('id').limit(1);
    ready = !error || !/42P01|does not exist|schema cache|relation/i.test(error.message || '');
  } catch (e) {
    ready = false;
  }
  return ready;
}

async function flush() {
  clearTimeout(timer);
  timer = null;
  if (!queue.length) return;
  if (sent >= MAX_PER_SESSION) { queue = []; return; }
  /* До входа user_id ещё нет — запись упрётся в RLS (401) и засорит консоль
     у всех, кто просто открыл страницу. Копим до появления сессии. */
  if (!S.me?.id) { queue = []; return; }
  /* SDK мог ещё не догрузиться — не теряем события, повторим позже. */
  if (!(await ensureClient())) {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) queue = [];
    else schedule();
    return;
  }
  if (!(await tableReady())) { queue = []; return; }

  const batch = queue.splice(0, 20);
  sent += batch.length;
  const rows = batch.map((e) => ({
    user_id: S.me?.id || null,
    kind: String(e.kind || 'unknown').slice(0, 60),
    data: sanitize(e.data),
    app_version: APP.version,
  }));
  try {
    const { error } = await sb.from('client_events').insert(rows);
    if (error) {
      /* таблицы нет — больше не пытаемся */
      if (/42P01|does not exist|schema cache|relation/i.test(error.message || '')) ready = false;
    }
  } catch (e) { /* сеть — просто теряем батч */ }
  if (queue.length) schedule();
}

function schedule() {
  if (timer) return;
  timer = setTimeout(flush, BATCH_MS);
}

export function logEvent(kind, data = {}) {
  try {
    if (!real()) return;
    if (sent >= MAX_PER_SESSION && !queue.length) return;
    queue.push({ kind, data });
    if (queue.length >= 20) flush();
    else schedule();
  } catch (e) { /* телеметрия не должна ломать приложение */ }
}

export function initTelemetry() {
  if (!real()) return;
  window.addEventListener('error', (e) => {
    logEvent('js_error', {
      message: String(e.message || '').slice(0, 200),
      source: String(e.filename || '').split('/').pop(),
      line: e.lineno,
      col: e.colno,
    });
  });
  window.addEventListener('unhandledrejection', (e) => {
    const r = e.reason;
    logEvent('promise_rejection', {
      message: String(r?.message || r || '').slice(0, 200),
      code: r?.code,
    });
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') flush();
  });
  window.addEventListener('online', () => logEvent('network_online'));
  window.addEventListener('offline', () => logEvent('network_offline'));
  observeVitals();
}

/* Замер конкретной операции (открытие чата, отправка) — в миллисекундах.
   Держим последние 200 замеров в window.__relikPerf: это бесплатный профайлер
   для отладки и замеров на реальном устройстве (DevTools → __relikPerf). */
export function markTiming(name, ms, extra = {}) {
  if (!Number.isFinite(ms)) return;
  try {
    const buf = (window.__relikPerf ||= []);
    buf.push({ name, ms: Math.round(ms), ...extra, at: Date.now() });
    if (buf.length > 200) buf.shift();
  } catch (e) { /* не критично */ }
  logEvent('perf_' + String(name).slice(0, 30), { ms: Math.round(ms), ...extra });
}

/* Web-vitals без зависимостей: LCP, CLS, INP-приближение, TTFB.
   Отправляем один раз — при уходе со страницы или через 15 с. */
function observeVitals() {
  const nav = performance.getEntriesByType?.('navigation')?.[0];
  if (nav) {
    logEvent('perf_nav', {
      ttfb: Math.round(nav.responseStart || 0),
      dcl: Math.round(nav.domContentLoadedEventEnd || 0),
      load: Math.round(nav.loadEventEnd || 0),
      transfer: nav.transferSize || 0,
    });
  }

  let lcp = 0;
  let cls = 0;
  let inp = 0;

  try {
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) lcp = Math.max(lcp, e.startTime);
    }).observe({ type: 'largest-contentful-paint', buffered: true });
  } catch (e) { /* Safari < 14.5 */ }

  try {
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) if (!e.hadRecentInput) cls += e.value;
    }).observe({ type: 'layout-shift', buffered: true });
  } catch (e) { /* нет LayoutShift */ }

  try {
    /* buffered для event-timing не поддерживается: observe() падал, и INP
       всегда уходил нулём. Считаем только настоящие взаимодействия. */
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) {
        if (!e.interactionId) continue;
        inp = Math.max(inp, e.duration);
      }
    }).observe({ type: 'event', durationThreshold: 40 });
  } catch (e) { /* нет Event Timing */ }

  let reported = false;
  const report = () => {
    if (reported) return;
    reported = true;
    const net = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    logEvent('perf_vitals', {
      lcp: Math.round(lcp),
      cls: Number(cls.toFixed(3)),
      inp: Math.round(inp),
      heap: performance.memory?.usedJSHeapSize || 0,
      v: APP.version,
      /* Контекст без персональных данных: помогает понять, где LCP p95 высокий. */
      ect: String(net?.effectiveType || ''),
      rtt: Number(net?.rtt) || 0,
      dm: Number(navigator.deviceMemory) || 0,
      hc: Number(navigator.hardwareConcurrency) || 0,
    });
  };

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') report();
  });
  setTimeout(report, 15000);
}
